source:
source note sys.dataset(fields: [title, subtitle, status, summary, metric1_label, metric1_value, metric2_label, metric2_value, as_of])

copy sim { class: vocabulary, en: "Simulation" }

view root Surface(pad: .tight) {
  Col(gap: 8) {
    Row(gap: 8, align: .center) {
      Icon(name: .mail, size: .row)
      TextCaption(text: copy.sim, width: .fill)
      TextCaption(value: note.as_of)
    }
    TextTitle(text: note.title, width: .fill)
    TextCaption(value: note.subtitle)
    TextCaption(value: note.status)
    Row(gap: 8, align: .center) {
      TextCaption(value: note.metric1_label)
      TextBody(text: note.metric1_value, width: .fill)
    }
    Row(gap: 8, align: .center) {
      TextCaption(value: note.metric2_label)
      TextBody(text: note.metric2_value, width: .fill)
    }
    TextBody(text: note.summary, width: .fill)
  }
}
